import {
  communitySchema,
  demoAccountSchema,
  feedItemSchema,
  feedPageSchema,
  mediaSchema,
  notificationPageSchema,
  profileSchema,
  reportSchema,
  searchResultSchema,
  sessionUserSchema,
  userSchema,
  whySchema,
  type CreateCommunityInput,
  type CreatePostInput,
  type CreateReportInput,
  type DefaultVisibility,
  type FeedMode,
} from '@pulse/shared';
import { z } from 'zod';

export class ApiError extends Error {
  constructor(
    readonly status: number,
    message: string,
    readonly code: string = 'error',
  ) {
    super(message);
  }
}

const errorBody = z.object({ error: z.object({ message: z.string(), code: z.string().optional() }) });

// Every response is checked against the same schema the server uses to build it.
async function request<S extends z.ZodType>(
  path: string,
  schema: S,
  init: RequestInit & { json?: unknown } = {},
): Promise<z.output<S>> {
  const { json, ...rest } = init;
  const res = await fetch(`/api${path}`, {
    ...rest,
    body: json === undefined ? rest.body : JSON.stringify(json),
    headers: { ...(json === undefined ? {} : { 'Content-Type': 'application/json' }), ...rest.headers },
    credentials: 'same-origin',
  });

  if (res.status === 204) return schema.parse(undefined);
  const body: unknown = await res.json().catch(() => null);
  if (!res.ok) {
    const parsed = errorBody.safeParse(body);
    throw new ApiError(
      res.status,
      parsed.data?.error.message ?? 'Something went wrong. Try again.',
      parsed.data?.error.code,
    );
  }
  return schema.parse(body);
}

const nothing = z.undefined();
const query = (params: Record<string, string | undefined>) => {
  const search = new URLSearchParams();
  for (const [key, value] of Object.entries(params)) if (value !== undefined) search.set(key, value);
  const text = search.toString();
  return text ? `?${text}` : '';
};

export const api = {
  // ---- session ----
  // The signed-in user, or null when there is no session.
  async me() {
    try {
      return (await request('/auth/me', z.object({ user: sessionUserSchema }))).user;
    } catch (error) {
      if (error instanceof ApiError && error.status === 401) return null;
      throw error;
    }
  },
  async continueAsGuest() {
    return (await request('/auth/guest', z.object({ user: sessionUserSchema }), { method: 'POST' })).user;
  },
  // The seeded accounts, or an empty list when the demo login is switched off.
  async demoAccounts() {
    try {
      return (await request('/auth/demo-accounts', z.object({ accounts: z.array(demoAccountSchema) }))).accounts;
    } catch (error) {
      if (error instanceof ApiError && error.status === 404) return [];
      throw error;
    }
  },
  async demoLogin(handle: string) {
    return (await request('/auth/demo', z.object({ user: sessionUserSchema }), { method: 'POST', json: { handle } })).user;
  },
  logout: () => request('/auth/logout', nothing, { method: 'POST' }),
  async setDefaultVisibility(defaultVisibility: DefaultVisibility) {
    return (await request('/auth/settings', z.object({ user: sessionUserSchema }), { method: 'PATCH', json: { defaultVisibility } })).user;
  },

  // ---- feeds ----
  feed: (mode: FeedMode, cursor?: string) => request(`/feed${query({ mode, cursor })}`, feedPageSchema),
  userPosts: (handle: string, cursor?: string) => request(`/users/${handle}/posts${query({ cursor })}`, feedPageSchema),
  communityPosts: (slug: string, cursor?: string) => request(`/communities/${slug}/posts${query({ cursor })}`, feedPageSchema),
  replies: (postId: string, cursor?: string) => request(`/posts/${postId}/replies${query({ cursor })}`, feedPageSchema),

  // ---- posts ----
  async post(id: string) {
    return (await request(`/posts/${id}`, z.object({ post: feedItemSchema }))).post;
  },
  async createPost(input: CreatePostInput) {
    return (await request('/posts', z.object({ post: feedItemSchema }), { method: 'POST', json: input })).post;
  },
  async createReply(postId: string, text: string) {
    return (await request(`/posts/${postId}/replies`, z.object({ post: feedItemSchema }), { method: 'POST', json: { text } })).post;
  },
  react: (postId: string) => request(`/posts/${postId}/reaction`, z.object({ reactions: z.number(), reacted: z.boolean() }), { method: 'PUT' }),
  unreact: (postId: string) => request(`/posts/${postId}/reaction`, z.object({ reactions: z.number(), reacted: z.boolean() }), { method: 'DELETE' }),
  why: (postId: string) => request(`/posts/${postId}/why`, whySchema),
  report: (postId: string, input: CreateReportInput) => request(`/posts/${postId}/report`, nothing, { method: 'POST', json: input }),

  // ---- people ----
  async profile(handle: string) {
    return (await request(`/users/${handle}`, z.object({ profile: profileSchema }))).profile;
  },
  follow: (handle: string) => request(`/users/${handle}/follow`, nothing, { method: 'PUT' }),
  unfollow: (handle: string) => request(`/users/${handle}/follow`, nothing, { method: 'DELETE' }),
  block: (handle: string) => request(`/users/${handle}/block`, nothing, { method: 'PUT' }),
  unblock: (handle: string) => request(`/users/${handle}/block`, nothing, { method: 'DELETE' }),
  async blockedUsers() {
    return (await request('/users/blocked', z.object({ users: z.array(userSchema) }))).users;
  },

  // ---- communities ----
  async communities() {
    return (await request('/communities', z.object({ communities: z.array(communitySchema) }))).communities;
  },
  async community(slug: string) {
    return (await request(`/communities/${slug}`, z.object({ community: communitySchema }))).community;
  },
  async createCommunity(input: CreateCommunityInput) {
    return (await request('/communities', z.object({ community: communitySchema }), { method: 'POST', json: input })).community;
  },
  join: (slug: string) => request(`/communities/${slug}/membership`, nothing, { method: 'PUT' }),
  leave: (slug: string) => request(`/communities/${slug}/membership`, nothing, { method: 'DELETE' }),

  // ---- images ----
  async uploadImage(file: File) {
    return (await request('/media', z.object({ media: mediaSchema }), { method: 'POST', body: file, headers: { 'Content-Type': file.type || 'application/octet-stream' } })).media;
  },
  async imageStatus(id: string) {
    return (await request(`/media/${id}`, z.object({ media: mediaSchema }))).media;
  },

  // ---- notifications, search, moderation ----
  notifications: (cursor?: string) => request(`/notifications${query({ cursor })}`, notificationPageSchema),
  async unreadCount() {
    return (await request('/notifications/unread-count', z.object({ count: z.number() }))).count;
  },
  markRead: () => request('/notifications/read', nothing, { method: 'POST' }),
  search: (q: string) => request(`/search${query({ q })}`, searchResultSchema),
  async reports() {
    return (await request('/moderation/reports', z.object({ reports: z.array(reportSchema) }))).reports;
  },
  resolveReport: (id: string, action: 'remove' | 'dismiss') =>
    request(`/moderation/reports/${id}/resolve`, nothing, { method: 'POST', json: { action } }),
};

// Measurements from this browser. They carry no personal data and are never allowed to fail loudly.
export function sendVitals(vitals: { scrollFps?: number; notificationDeliveryMs?: number }) {
  try {
    void fetch('/api/telemetry/vitals', {
      method: 'POST',
      keepalive: true,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(vitals),
    });
  } catch {
    // measuring must never get in the way
  }
}
